import sys
from collections import defaultdict

def main():
    import sys
    import heapq

    def readints():
        return list(map(int, sys.stdin.readline().split()))

    n, m = readints()
    a = readints()
    segments = [readints() for _ in range(m)]

    if m == 0:
        print(0)
        print(0)
        return

    # Create a dictionary to store the segments that cover each index
    index_segments = defaultdict(list)
    for i, (l, r) in enumerate(segments):
        for j in range(l-1, r):
            index_segments[j].append(i)

    # Initialize the dp table
    dp = [[-float('inf')] * (1 << m) for _ in range(n)]
    parent = [[None] * (1 << m) for _ in range(n)]

    # Base case: no segments applied
    for i in range(n):
        dp[i][0] = a[i]

    # Fill the dp table
    for mask in range(1, 1 << m):
        for i in range(n):
            if dp[i][mask] == -float('inf'):
                continue
            for j in index_segments[i]:
                if mask & (1 << j):
                    new_mask = mask ^ (1 << j)
                    if dp[i][new_mask] + 1 > dp[i][mask]:
                        dp[i][mask] = dp[i][new_mask] + 1
                        parent[i][mask] = (i, new_mask)

    # Find the maximum difference
    max_diff = -float('inf')
    best_mask = 0
    for mask in range(1 << m):
        current_max = max(dp[i][mask] for i in range(n))
        current_min = min(dp[i][mask] for i in range(n))
        if current_max - current_min > max_diff:
            max_diff = current_max - current_min
            best_mask = mask

    # Reconstruct the path
    path = []
    current_mask = best_mask
    for i in range(n-1, -1, -1):
        if current_mask == 0:
            break
        if parent[i][current_mask] is None:
            continue
        prev_i, prev_mask = parent[i][current_mask]
        for j in index_segments[i]:
            if current_mask & (1 << j) and prev_mask & (1 << j) == 0:
                path.append(j + 1)
                break
        current_mask = prev_mask

    # Output the result
    print(max_diff)
    print(len(path))
    print(*path)

if __name__ == "__main__":
    main()
